CREATE FUNCTION pactwoven.custody_hash(k text,v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT pactwoven.finance_hash(jsonb_build_object('namespace',CASE k WHEN 'specification' THEN 'pactwoven:custody-setup-specification:v1' WHEN 'owner_binding' THEN 'pactwoven:custody-owner-binding:v1'
 WHEN 'evidence' THEN 'pactwoven:custody-auth-evidence:v1' WHEN 'command' THEN 'pactwoven:custody-command:v1' ELSE 'pactwoven:custody-'||k||':v1' END,'record',v))
$$;
CREATE FUNCTION pactwoven.custody_require(k text,v jsonb) RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
BEGIN IF octet_length(v::text)>65536 OR NOT pactwoven.custody_matches(v,pactwoven.custody_schema(k)) THEN RAISE EXCEPTION USING ERRCODE='CS004',MESSAGE='Invalid custody record';END IF;END $$;
CREATE FUNCTION pactwoven.custody_ref(v jsonb,h text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('id',v->'id','version',v->'version','recordHash',h)
$$;
CREATE FUNCTION pactwoven.custody_nonce() RETURNS text LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
 SELECT translate(rtrim(encode(sha256(uuid_send(gen_random_uuid())||uuid_send(gen_random_uuid())||uuid_send(gen_random_uuid())),'base64'),'='),'+/','-_')
$$;
CREATE FUNCTION pactwoven.custody_pow(n numeric,e numeric,p numeric) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE r numeric:=1;BEGIN n:=mod(mod(n,p)+p,p);WHILE e>0 LOOP IF mod(e,2)=1 THEN r:=mod(r*n,p);END IF;n:=mod(n*n,p);e:=div(e,2);END LOOP;RETURN r;END $$;
CREATE FUNCTION pactwoven.custody_pda(program bytea,seeds bytea) RETURNS bytea LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE b int;i int;v bytea;y numeric;yy numeric;x numeric;p constant numeric:=57896044618658097711785492504343953926634992332820282019728792003956564819949;
 d constant numeric:=37095705934669439343138083508754565189542113879843219016388785533085940283555;
BEGIN
 FOR b IN REVERSE 255..0 LOOP
  v:=sha256(seeds||set_byte(decode('00','hex'),0,b)||program||convert_to('ProgramDerivedAddress','UTF8'));y:=0;
  FOR i IN REVERSE 31..0 LOOP y:=y*256+(CASE WHEN i=31 THEN get_byte(v,i)&127 ELSE get_byte(v,i) END);END LOOP;
  yy:=mod(y*y,p);x:=mod(mod((yy-1)*pactwoven.custody_pow(d*yy+1,p-2,p),p)+p,p);
  IF x<>0 AND pactwoven.custody_pow(x,(p-1)/2,p)<>1 THEN RETURN v;END IF;
 END LOOP;RAISE EXCEPTION USING ERRCODE='CS004',MESSAGE='No custody address';END $$;
CREATE FUNCTION pactwoven.custody_spec_valid(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE program bytea;org bytea;resp bytea;reg bytea;pub text;fee numeric;rent numeric;BEGIN
 PERFORM pactwoven.custody_require('specification',v);
 IF v#>>'{organization,registrationUuid}'='00000000-0000-0000-0000-000000000000' OR v#>>'{responsibility,registrationUuid}'='00000000-0000-0000-0000-000000000000'
  OR ((v->>'version')::int=1) IS DISTINCT FROM (v->'predecessor'='null'::jsonb)
  OR ((v->>'version')::int>1 AND (v#>>'{predecessor,id}'<>v->>'id' OR (v#>>'{predecessor,version}')::int+1<>(v->>'version')::int))
  OR v->>'ownerWalletPublicKey'=v->>'registrar' OR v#>>'{site,id}'<>v#>>'{responsibility,siteId}'
  OR v#>>'{authority,snapshot,environment}'<>v->>'environment' OR v#>>'{authority,snapshot,organizationId}'<>v#>>'{organization,id}'
  OR v#>'{authority,snapshot,responsibility}' IS DISTINCT FROM ((v->'responsibility')-'registrationUuid')
  OR (v#>>'{authority,snapshot,family}'='none') IS DISTINCT FROM (v#>'{authority,snapshot,legacyHead}'='null'::jsonb)
  OR v#>>'{authority,recordHash}'<>pactwoven.finance_hash(jsonb_build_object('namespace','pactwoven:financial-authority-fence:v1','record',v#>'{authority,snapshot}'))
  OR (v->>'expiresAt')::timestamptz<=(v->>'issuedAt')::timestamptz THEN RETURN false;END IF;
 FOREACH pub IN ARRAY ARRAY[v->>'ownerWalletPublicKey',v#>>'{program,id}',v#>>'{program,programData}',v#>>'{config,address}',v->>'registrationAddress',v->>'vaultAddress',v->>'registrar',v->>'rentPayer'] LOOP
  IF pactwoven.finance_base58(pub,32)=decode(repeat('00',32),'hex') THEN RETURN false;END IF;
 END LOOP;
 FOR pub IN SELECT value FROM jsonb_each_text((v->'transactionPolicy')-ARRAY['reference','instructionPlanHash']) LOOP
  IF pub::numeric>18446744073709551615 THEN RETURN false;END IF;
 END LOOP;
 fee:=(v#>>'{transactionPolicy,maximumFeeLamports}')::numeric;rent:=(v#>>'{transactionPolicy,maximumRentLamports}')::numeric;
 IF fee<=0 OR rent<=0 OR (v#>>'{transactionPolicy,maximumTotalLamports}')::numeric<fee+rent OR(v#>>'{program,deploymentSlot}')::numeric>18446744073709551615 THEN RETURN false;END IF;
 program:=pactwoven.finance_base58(v#>>'{program,id}',32);
 org:=sha256(convert_to('pactwoven:org-registration:v1','UTF8')||decode('00','hex')||uuid_send((v#>>'{organization,registrationUuid}')::uuid));
 resp:=sha256(convert_to('pactwoven:responsibility-registration:v1','UTF8')||decode('00','hex')||uuid_send((v#>>'{organization,registrationUuid}')::uuid)||uuid_send((v#>>'{responsibility,registrationUuid}')::uuid));
 reg:=pactwoven.custody_pda(program,convert_to('pw:custody:v1','UTF8')||org||resp||decode(v#>>'{asset,key}','hex'));
 RETURN pactwoven.finance_base58(v#>>'{config,address}',32)=pactwoven.custody_pda(program,convert_to('pw:config:v1','UTF8'))
  AND pactwoven.finance_base58(v->>'registrationAddress',32)=reg
  AND pactwoven.finance_base58(v->>'vaultAddress',32)=pactwoven.custody_pda(program,convert_to('pw:vault:v1','UTF8')||reg)
  AND v->>'setupOperationKey'=encode(sha256(convert_to('pactwoven:custody-setup-op:v1','UTF8')||decode('00','hex')||program||reg),'hex');
END $$;

CREATE TABLE pactwoven.custody_setup_principals(
 principal_oid oid NOT NULL,principal_name text NOT NULL,organization_id text NOT NULL,environment text NOT NULL CHECK(environment='development'),
 capability text NOT NULL CHECK(capability IN('writer','verifier')),version integer NOT NULL CHECK(version>0),active boolean NOT NULL,expires_at timestamptz NOT NULL,
 PRIMARY KEY(principal_oid,organization_id,version),FOREIGN KEY(environment,organization_id) REFERENCES pactwoven.organizations(environment,id));
CREATE TABLE pactwoven.custody_setup_organization_ids(environment text NOT NULL CHECK(environment='development'),organization_id text NOT NULL,registration_uuid uuid NOT NULL CHECK(registration_uuid<>'00000000-0000-0000-0000-000000000000'),
 PRIMARY KEY(environment,organization_id),UNIQUE(registration_uuid),FOREIGN KEY(environment,organization_id) REFERENCES pactwoven.organizations(environment,id));
CREATE TABLE pactwoven.custody_setup_responsibility_ids(environment text NOT NULL CHECK(environment='development'),organization_id text NOT NULL,responsibility_id text NOT NULL,registration_uuid uuid NOT NULL CHECK(registration_uuid<>'00000000-0000-0000-0000-000000000000'),
 PRIMARY KEY(environment,organization_id,responsibility_id),UNIQUE(registration_uuid),FOREIGN KEY(environment,organization_id,responsibility_id) REFERENCES pactwoven.responsibilities(environment,organization_id,id));
CREATE TABLE pactwoven.custody_setup_specifications(id text NOT NULL,version integer NOT NULL CHECK(version>0),body jsonb NOT NULL CHECK(pactwoven.custody_spec_valid(body)),
 hash text GENERATED ALWAYS AS(pactwoven.custody_hash('specification',body)) STORED,PRIMARY KEY(id,version),CHECK(body->>'id'=id AND (body->>'version')::int=version));
CREATE TABLE pactwoven.custody_setup_specification_controls(specification_id text NOT NULL,generation integer NOT NULL CHECK(generation>=0),version integer NOT NULL,active boolean NOT NULL,
 PRIMARY KEY(specification_id,generation),FOREIGN KEY(specification_id,version) REFERENCES pactwoven.custody_setup_specifications(id,version));
CREATE TABLE pactwoven.custody_setup_evidence(id uuid PRIMARY KEY,kind text NOT NULL,organization_id text NOT NULL,body jsonb NOT NULL,
 hash text GENERATED ALWAYS AS(pactwoven.custody_hash('evidence',body)) STORED,principal_oid oid NOT NULL,principal_name text NOT NULL,principal_version integer NOT NULL CHECK(principal_version>0),
 CHECK(pactwoven.custody_matches(body,pactwoven.custody_schema('evidence')) AND body->>'id'=id::text AND body->>'kind'=kind AND body->>'organizationId'=organization_id));
CREATE TABLE pactwoven.custody_setup_anchors(id uuid PRIMARY KEY,environment text NOT NULL CHECK(environment='development'),organization_id text NOT NULL,responsibility_id text NOT NULL,asset_key text NOT NULL,setup_operation_key text NOT NULL,
 UNIQUE(environment,organization_id,responsibility_id,asset_key),UNIQUE(setup_operation_key),FOREIGN KEY(environment,organization_id,responsibility_id) REFERENCES pactwoven.responsibilities(environment,organization_id,id));
CREATE TABLE pactwoven.custody_setup_operations(id uuid PRIMARY KEY,organization_id text NOT NULL,actor_id text NOT NULL,responsibility_id text NOT NULL,kind text NOT NULL,key text NOT NULL,
 command_hash text NOT NULL,command jsonb NOT NULL,result jsonb NOT NULL,UNIQUE(organization_id,actor_id,kind,key));
CREATE TABLE pactwoven.custody_setup_records(id uuid PRIMARY KEY,setup_id uuid NOT NULL REFERENCES pactwoven.custody_setup_anchors(id),kind text NOT NULL,version integer NOT NULL CHECK(version>0),body jsonb NOT NULL,
 hash text GENERATED ALWAYS AS(pactwoven.custody_hash(kind,body)) STORED,operation_id uuid NOT NULL UNIQUE REFERENCES pactwoven.custody_setup_operations(id) DEFERRABLE INITIALLY DEFERRED,
 CHECK(pactwoven.custody_matches(body,pactwoven.custody_schema('record')) AND body->>'id'=id::text AND body->>'setupId'=setup_id::text AND body->>'kind'=kind AND(body->>'version')::int=version));
CREATE UNIQUE INDEX custody_one_binding ON pactwoven.custody_setup_records(setup_id) WHERE kind='owner_binding';
CREATE UNIQUE INDEX custody_draft_versions ON pactwoven.custody_setup_records(setup_id,version) WHERE kind='draft';
CREATE UNIQUE INDEX custody_one_wallet_challenge ON pactwoven.custody_setup_records((body#>>'{draft,id}')) WHERE kind='wallet_challenge';
CREATE UNIQUE INDEX custody_one_confirmation ON pactwoven.custody_setup_records((body#>>'{intent,challenge,id}')) WHERE kind='confirmation';
CREATE TABLE pactwoven.custody_setup_controls(setup_id uuid NOT NULL REFERENCES pactwoven.custody_setup_anchors(id),generation integer NOT NULL CHECK(generation>=0),draft_id uuid NOT NULL REFERENCES pactwoven.custody_setup_records(id) DEFERRABLE INITIALLY DEFERRED,
 state text NOT NULL CHECK(state IN('pending','confirmed','cancelled')),operation_id uuid NOT NULL UNIQUE REFERENCES pactwoven.custody_setup_operations(id) DEFERRABLE INITIALLY DEFERRED,PRIMARY KEY(setup_id,generation));
CREATE TABLE pactwoven.custody_setup_audit(operation_id uuid PRIMARY KEY REFERENCES pactwoven.custody_setup_operations(id) DEFERRABLE INITIALLY DEFERRED,body jsonb NOT NULL);
CREATE TABLE pactwoven.custody_setup_outbox(operation_id uuid PRIMARY KEY REFERENCES pactwoven.custody_setup_operations(id) DEFERRABLE INITIALLY DEFERRED,body jsonb NOT NULL);
CREATE TABLE pactwoven.custody_setup_evidence_uses(evidence_id uuid PRIMARY KEY REFERENCES pactwoven.custody_setup_evidence(id),operation_id uuid NOT NULL REFERENCES pactwoven.custody_setup_operations(id) DEFERRABLE INITIALLY DEFERRED);

CREATE FUNCTION pactwoven.custody_principal(o text,cap text) RETURNS oid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r record;p record;unsafe boolean;BEGIN
 SELECT * INTO r FROM pg_roles WHERE rolname=SESSION_USER;
 WITH RECURSIVE reachable(oid) AS(SELECT r.oid UNION SELECT m.roleid FROM pg_auth_members m JOIN reachable x ON x.oid=m.member)
 SELECT EXISTS(SELECT 1 FROM reachable x JOIN pg_roles q ON q.oid=x.oid WHERE q.rolsuper OR q.rolbypassrls OR q.rolcreatedb OR q.rolcreaterole OR q.rolreplication
 OR q.rolname IN('pactwoven_runtime','pactwoven_provisioner','pactwoven_access_provisioner','pactwoven_mandate_writer','pactwoven_finance_observer',CASE cap WHEN 'writer' THEN 'pactwoven_custody_setup_verifier' ELSE 'pactwoven_custody_setup_writer' END)) INTO unsafe;
 IF coalesce(unsafe,true) OR current_setting('role')<>'none' OR r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication OR NOT r.rolcanlogin
 OR NOT pg_has_role(r.oid,'pactwoven_custody_setup_'||cap,'USAGE') THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Dedicated authenticated setup principal required';END IF;
 SELECT * INTO p FROM pactwoven.custody_setup_principals WHERE principal_oid=r.oid AND organization_id=o ORDER BY version DESC LIMIT 1;
 IF p.principal_name IS DISTINCT FROM r.rolname OR p.capability IS DISTINCT FROM cap OR NOT coalesce(p.active,false) OR p.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Current setup principal binding required';END IF;RETURN r.oid;
END $$;
CREATE FUNCTION pactwoven.custody_evidence_current(eid uuid,o text) RETURNS boolean LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM pactwoven.custody_setup_evidence e JOIN pg_roles r ON r.oid=e.principal_oid AND r.rolname=e.principal_name
 JOIN LATERAL(SELECT * FROM pactwoven.custody_setup_principals p WHERE p.principal_oid=e.principal_oid AND p.organization_id=o ORDER BY version DESC LIMIT 1)p ON true
 WHERE e.id=eid AND e.organization_id=o AND p.environment='development' AND p.principal_name=r.rolname AND p.capability='verifier' AND p.version=e.principal_version AND p.active AND p.expires_at>clock_timestamp()
 AND pg_has_role(r.oid,'pactwoven_custody_setup_verifier','USAGE') AND r.rolcanlogin AND NOT r.rolsuper AND NOT r.rolbypassrls)
$$;
CREATE FUNCTION pactwoven.custody_context(eid uuid,rid text,cap text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='3s' AS $$
DECLARE e jsonb;o pactwoven.organizations%ROWTYPE;m pactwoven.memberships%ROWTYPE;r pactwoven.responsibilities%ROWTYPE;BEGIN
 PERFORM pactwoven.financial_require_read_committed();
 SELECT body INTO e FROM pactwoven.custody_setup_evidence WHERE id=eid AND kind='identity';
 IF e IS NULL THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Private identity evidence required';END IF;
 SELECT * INTO o FROM pactwoven.organizations WHERE environment='development' AND id=e->>'organizationId' FOR UPDATE;
 LOCK TABLE pactwoven.session_revocations IN SHARE MODE;
 PERFORM actor_id FROM pactwoven.memberships WHERE environment='development' AND organization_id=o.id ORDER BY actor_id FOR SHARE;
 SELECT * INTO m FROM pactwoven.memberships WHERE environment='development' AND organization_id=o.id AND actor_id=e#>>'{owner,actorId}';
 IF o.status IS DISTINCT FROM 'active' OR o.external_organization_id IS DISTINCT FROM e->>'externalOrganizationId'
  OR m.status IS DISTINCT FROM 'active' OR NOT('owner'=ANY(m.roles)) OR m.external_subject IS DISTINCT FROM e#>>'{owner,subject}'
  OR m.external_membership_id IS DISTINCT FROM e#>>'{owner,externalMembershipId}' OR m.row_version IS DISTINCT FROM(e#>>'{owner,membershipVersion}')::int
  OR(m.grant_basis='clerk_admin_bootstrap' AND e->>'externalRole' IS DISTINCT FROM 'org:admin')
  OR(m.expires_at IS NOT NULL AND m.expires_at<=clock_timestamp()) OR(e->>'observedAt')::timestamptz>clock_timestamp() OR(e->>'observedAt')::timestamptz<clock_timestamp()-interval '20 seconds'
  OR(e->>'expiresAt')::timestamptz<=clock_timestamp() OR EXISTS(SELECT 1 FROM pactwoven.session_revocations WHERE environment='development' AND session_id=e#>>'{owner,sessionId}') THEN
  RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Current owner identity required';END IF;
 SELECT * INTO r FROM pactwoven.responsibilities WHERE environment='development' AND organization_id=o.id AND id=rid FOR SHARE;
 PERFORM id FROM pactwoven.sites WHERE environment='development' AND organization_id=o.id ORDER BY id FOR SHARE;
 IF r.id IS NULL OR NOT EXISTS(SELECT 1 FROM pactwoven.site_memberships WHERE environment='development' AND organization_id=o.id AND actor_id=m.actor_id AND site_id=r.site_id)
  OR NOT EXISTS(SELECT 1 FROM pactwoven.member_action_sites WHERE environment='development' AND organization_id=o.id AND actor_id=m.actor_id AND site_id=r.site_id) THEN
  RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Exact current setup site grants required';END IF;
 PERFORM responsibility_id FROM pactwoven.financial_authority_fences WHERE environment='development' AND organization_id=o.id AND responsibility_id=rid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Canonical scope unavailable';END IF;
 IF(e->>'observedAt')::timestamptz<clock_timestamp()-interval '20 seconds' OR(e->>'expiresAt')::timestamptz<=clock_timestamp()
 OR(m.expires_at IS NOT NULL AND m.expires_at<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Owner expired while waiting';END IF;
 PERFORM pactwoven.custody_principal(o.id,cap);
 IF NOT pactwoven.custody_evidence_current(eid,o.id) THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Identity verifier binding changed';END IF;
 RETURN jsonb_build_object('organizationId',o.id,'actorId',m.actor_id,'identity',e,'organizationEpoch',o.authority_epoch,'responsibility',pactwoven.mandate_responsibility_body(r));
END $$;
CREATE FUNCTION pactwoven.custody_assert_spec(c jsonb,s jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a pactwoven.financial_authority_fences%ROWTYPE;f pactwoven.financial_site_fences%ROWTYPE;ac pactwoven.finance_asset_controls%ROWTYPE;af pactwoven.financial_asset_fences%ROWTYPE;av jsonb;sc record;BEGIN
 SELECT * INTO a FROM pactwoven.financial_authority_fences WHERE environment='development' AND organization_id=c->>'organizationId' AND responsibility_id=c#>>'{responsibility,id}';
 SELECT * INTO f FROM pactwoven.financial_site_fences WHERE environment='development' AND organization_id=c->>'organizationId' AND site_id=c#>>'{responsibility,siteId}';
 SELECT * INTO ac FROM pactwoven.finance_asset_controls WHERE asset_key=s#>>'{asset,key}' FOR SHARE;
 SELECT * INTO af FROM pactwoven.financial_asset_fences WHERE asset_key=s#>>'{asset,key}' FOR SHARE;
 SELECT to_jsonb(v) INTO av FROM pactwoven.finance_asset_versions v WHERE asset_key=ac.asset_key AND version=ac.current_version;
 SELECT * INTO sc FROM pactwoven.custody_setup_specification_controls WHERE specification_id=s->>'id' ORDER BY generation DESC LIMIT 1 FOR SHARE;
 IF s#>>'{organization,id}' IS DISTINCT FROM c->>'organizationId' OR s#>'{organization,authorityEpoch}' IS DISTINCT FROM c->'organizationEpoch'
  OR s->'owner' IS DISTINCT FROM c#>'{identity,owner}' OR s#>>'{responsibility,id}' IS DISTINCT FROM c#>>'{responsibility,id}'
  OR (s#>>'{responsibility,version}')::int IS DISTINCT FROM (c#>>'{responsibility,version}')::int
  OR s#>>'{responsibility,hash}' IS DISTINCT FROM pactwoven.finance_hash(c->'responsibility')
  OR s#>'{authority,snapshot}' IS DISTINCT FROM pactwoven.financial_authority_snapshot(a)
  OR s#>>'{authority,recordHash}' IS DISTINCT FROM pactwoven.financial_authority_fence_hash(a)
  OR NOT coalesce(f.active,false) OR s#>>'{site,id}' IS DISTINCT FROM f.site_id OR (s#>>'{site,generation}')::int IS DISTINCT FROM f.generation
  OR s#>>'{site,recordHash}' IS DISTINCT FROM f.record_hash
  OR NOT coalesce(ac.accepts_observations,false) OR ac.revoked_at IS NOT NULL OR ac.current_version IS DISTINCT FROM(s#>>'{asset,registryVersion}')::int
  OR s#>>'{asset,registryRecordHash}' IS DISTINCT FROM pactwoven.finance_hash(av)
  OR(s#>>'{asset,controlGeneration}')::int IS DISTINCT FROM af.generation OR s#>>'{asset,controlHash}' IS DISTINCT FROM af.control_hash
  OR NOT coalesce(sc.active,false) OR sc.version IS DISTINCT FROM(s->>'version')::int
  OR NOT EXISTS(SELECT 1 FROM pactwoven.custody_setup_organization_ids WHERE environment='development' AND organization_id=c->>'organizationId' AND registration_uuid=(s#>>'{organization,registrationUuid}')::uuid)
  OR NOT EXISTS(SELECT 1 FROM pactwoven.custody_setup_responsibility_ids WHERE environment='development' AND organization_id=c->>'organizationId' AND responsibility_id=c#>>'{responsibility,id}' AND registration_uuid=(s#>>'{responsibility,registrationUuid}')::uuid)
 THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Reviewed custody scope changed';END IF;
 IF (s->>'issuedAt')::timestamptz>clock_timestamp() OR(s->>'expiresAt')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='CS003',MESSAGE='Reviewed setup expired';END IF;
END $$;
CREATE FUNCTION pactwoven.custody_setup_attest(v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='3s' AS $$
DECLARE who oid;old jsonb;o pactwoven.organizations%ROWTYPE;m pactwoven.memberships%ROWTYPE;link jsonb;e jsonb;intent jsonb;h text;BEGIN
 PERFORM pactwoven.financial_require_read_committed();PERFORM pactwoven.custody_require('evidence',v);
 SELECT * INTO o FROM pactwoven.organizations WHERE environment='development' AND id=v->>'organizationId' FOR UPDATE;
 LOCK TABLE pactwoven.session_revocations IN SHARE MODE;
 PERFORM actor_id FROM pactwoven.memberships WHERE environment='development' AND organization_id=o.id ORDER BY actor_id FOR SHARE;
 SELECT * INTO m FROM pactwoven.memberships WHERE environment='development' AND organization_id=o.id AND actor_id=v#>>'{owner,actorId}';
 IF o.status IS DISTINCT FROM 'active' OR m.status IS DISTINCT FROM 'active' OR NOT('owner'=ANY(m.roles)) OR m.row_version IS DISTINCT FROM(v#>>'{owner,membershipVersion}')::int
 OR m.external_subject IS DISTINCT FROM v#>>'{owner,subject}' OR m.external_membership_id IS DISTINCT FROM v#>>'{owner,externalMembershipId}'
 OR(m.expires_at IS NOT NULL AND m.expires_at<=clock_timestamp()) OR EXISTS(SELECT 1 FROM pactwoven.session_revocations WHERE environment='development' AND session_id=v#>>'{owner,sessionId}')
 OR(v->>'observedAt')::timestamptz>clock_timestamp() OR(v->>'observedAt')::timestamptz<clock_timestamp()-interval '20 seconds'
 OR(v->>'expiresAt')::timestamptz<=clock_timestamp() OR(v->>'expiresAt')::timestamptz>(v->>'observedAt')::timestamptz+interval '5 minutes' THEN
 RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Current verifier owner observation required';END IF;
 IF v->>'kind' IN('identity','mfa') AND(o.external_organization_id IS DISTINCT FROM v->>'externalOrganizationId'
 OR(m.grant_basis='clerk_admin_bootstrap' AND v->>'externalRole' IS DISTINCT FROM 'org:admin') OR(v->>'tokenIssuedAt')::timestamptz>(v->>'observedAt')::timestamptz) THEN
 RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Exact identity issuer scope required';END IF;
 who:=pactwoven.custody_principal(o.id,'verifier');
 SELECT body INTO old FROM pactwoven.custody_setup_evidence WHERE id=(v->>'id')::uuid;
 IF old IS NOT NULL THEN IF old<>v THEN RAISE EXCEPTION USING ERRCODE='CS005',MESSAGE='Evidence identity conflict';END IF;RETURN pactwoven.custody_ref(v,pactwoven.custody_hash('evidence',v))||jsonb_build_object('version',1);END IF;
 IF v->>'kind'='wallet' THEN
  SELECT body INTO link FROM pactwoven.custody_setup_records WHERE id=(v#>>'{challenge,id}')::uuid AND kind='wallet_challenge';
  IF link IS NULL OR pactwoven.custody_ref(link,pactwoven.custody_hash('wallet_challenge',link)) IS DISTINCT FROM v->'challenge'
   OR link->'owner' IS DISTINCT FROM v->'owner' OR link->>'organizationId'<>o.id OR link->>'setupId'<>v->>'setupId'
   OR(v->>'expiresAt')::timestamptz>(link->>'expiresAt')::timestamptz OR(v->>'signatureHash')<>encode(sha256(decode(v->>'signature','base64')),'hex') THEN
   RAISE EXCEPTION USING ERRCODE='CS004',MESSAGE='Exact private wallet verification required';END IF;
 ELSIF v->>'kind'='mfa' THEN
  SELECT body INTO link FROM pactwoven.custody_setup_records WHERE id=(v->>'confirmationId')::uuid AND kind='confirmation';intent:=link->'intent';
  IF link IS NULL OR link->>'organizationId'<>o.id OR intent->'owner' IS DISTINCT FROM v->'owner' OR intent->>'nonce' IS DISTINCT FROM v->>'nonce'
   OR intent->>'key' IS DISTINCT FROM v->>'key' OR link->>'intentHash' IS DISTINCT FROM v->>'intentHash' OR link->>'requestHash' IS DISTINCT FROM v->>'requestHash'
   OR(v->>'verifiedAt')::timestamptz IS DISTINCT FROM (v->>'tokenIssuedAt')::timestamptz-(greatest((v->>'firstFactorAgeMinutes')::int,(v->>'secondFactorAgeMinutes')::int)+1)*interval '1 minute'
   OR(v->>'expiresAt')::timestamptz>(v->>'verifiedAt')::timestamptz+interval '5 minutes' OR(v->>'expiresAt')::timestamptz>(link->>'expiresAt')::timestamptz THEN
   RAISE EXCEPTION USING ERRCODE='CS004',MESSAGE='Exact fresh private MFA verification required';END IF;
 END IF;
 h:=pactwoven.custody_hash('evidence',v);
 INSERT INTO pactwoven.custody_setup_evidence(id,kind,organization_id,body,principal_oid,principal_name,principal_version) SELECT (v->>'id')::uuid,v->>'kind',o.id,v,who,SESSION_USER,version FROM pactwoven.custody_setup_principals WHERE principal_oid=who AND organization_id=o.id ORDER BY version DESC LIMIT 1;
 RETURN jsonb_build_object('id',v->'id','version',1,'recordHash',h);
END $$;
CREATE FUNCTION pactwoven.custody_command_hash(o text,a text,v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT pactwoven.custody_hash('command',jsonb_build_object('environment','development','organizationId',o,'actorId',a,'command',v))
$$;
CREATE FUNCTION pactwoven.custody_setup_command(eid uuid,v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET lock_timeout='3s' AS $$
#variable_conflict use_column
DECLARE c jsonb;s jsonb;d jsonb;ch jsonb;cf jsonb;w jsonb;mf jsonb;old jsonb;body jsonb;result jsonb;target jsonb;intent jsonb;common jsonb;
 anchor pactwoven.custody_setup_anchors%ROWTYPE;control pactwoven.custody_setup_controls%ROWTYPE;locked_control pactwoven.custody_setup_controls%ROWTYPE;prev pactwoven.custody_setup_records%ROWTYPE;
 opid uuid:=gen_random_uuid();recordid uuid:=gen_random_uuid();sid uuid;hash text;kind text:=v->>'kind';recordkind text;version int:=1;generation int;at_time timestamptz;expires timestamptz;spec_generation int;prep jsonb;
BEGIN
 PERFORM pactwoven.custody_require('command',v);c:=pactwoven.custody_context(eid,v->>'responsibilityId','writer');hash:=pactwoven.custody_command_hash(c->>'organizationId',c->>'actorId',v);
 SELECT result INTO old FROM pactwoven.custody_setup_operations WHERE organization_id=c->>'organizationId' AND actor_id=c->>'actorId' AND kind=v->>'kind' AND key=v->>'key';
 IF old IS NOT NULL THEN IF old->>'commandHash'<>hash THEN RAISE EXCEPTION USING ERRCODE='CS005',MESSAGE='Original setup key conflict';END IF;RETURN old;END IF;
 IF kind='prepare' THEN
  SELECT body INTO s FROM pactwoven.custody_setup_specifications WHERE id=v#>>'{reviewedSpecificationRef,id}' AND version=(v#>>'{reviewedSpecificationRef,version}')::int;
  IF s IS NULL OR pactwoven.custody_ref(s,pactwoven.custody_hash('specification',s)) IS DISTINCT FROM v->'reviewedSpecificationRef' OR s->>'ownerWalletPublicKey' IS DISTINCT FROM v->>'ownerWalletPublicKey' THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Exact reviewed specification required';END IF;
  PERFORM pactwoven.custody_assert_spec(c,s);
  IF v->'expectedScope' IS DISTINCT FROM jsonb_build_object('responsibilityVersion',s#>'{responsibility,version}','responsibilityHash',s#>'{responsibility,hash}',
   'siteGeneration',s#>'{site,generation}','siteRecordHash',s#>'{site,recordHash}','canonicalGeneration',s#>'{authority,snapshot,generation}','canonicalHash',s#>'{authority,recordHash}') THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Expected setup scope changed';END IF;
  SELECT * INTO anchor FROM pactwoven.custody_setup_anchors WHERE environment='development' AND organization_id=c->>'organizationId' AND responsibility_id=v->>'responsibilityId' AND asset_key=s#>>'{asset,key}' FOR UPDATE;
  IF anchor.id IS NULL THEN
   IF v->'previousDraft'<>'null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Unexpected draft predecessor';END IF;
   sid:=gen_random_uuid();INSERT INTO pactwoven.custody_setup_anchors VALUES(sid,'development',c->>'organizationId',v->>'responsibilityId',s#>>'{asset,key}',s->>'setupOperationKey');generation:=0;
  ELSE
   sid:=anchor.id;SELECT * INTO control FROM pactwoven.custody_setup_controls WHERE setup_id=sid ORDER BY generation DESC LIMIT 1 FOR UPDATE;
   SELECT * INTO prev FROM pactwoven.custody_setup_records WHERE id=control.draft_id;
   IF anchor.setup_operation_key IS DISTINCT FROM s->>'setupOperationKey' OR v->'previousDraft' IS DISTINCT FROM pactwoven.custody_ref(prev.body,prev.hash)
    OR prev.body->>'actorId' IS DISTINCT FROM c->>'actorId' OR EXISTS(SELECT 1 FROM pactwoven.custody_setup_records WHERE setup_id=sid AND kind='owner_binding') THEN
    RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Exact unbound draft predecessor required';END IF;
   generation:=pactwoven.financial_next_generation(control.generation);version:=pactwoven.financial_next_generation(prev.version);
  END IF;
  recordkind:='draft';
 ELSE
  sid:=(v->>'setupId')::uuid;SELECT * INTO anchor FROM pactwoven.custody_setup_anchors WHERE id=sid AND organization_id=c->>'organizationId' AND responsibility_id=v->>'responsibilityId';
  -- Resolve immutable draft/specification references under the organization lock.
  -- Earlier asset and specification tiers must precede any setup-control row lock.
  SELECT * INTO control FROM pactwoven.custody_setup_controls WHERE setup_id=sid ORDER BY generation DESC LIMIT 1;
  SELECT body INTO d FROM pactwoven.custody_setup_records WHERE id=control.draft_id;
  IF anchor.id IS NULL OR d->>'actorId' IS DISTINCT FROM c->>'actorId' OR(d->>'version')::int IS DISTINCT FROM(v->>'expectedSetupVersion')::int
    OR pactwoven.custody_hash('draft',d) IS DISTINCT FROM v->>'expectedSetupHash' THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Exact current draft required';END IF;
  SELECT body INTO s FROM pactwoven.custody_setup_specifications WHERE id=d#>>'{specification,id}' AND version=(d#>>'{specification,version}')::int;
  IF kind<>'cancel' THEN
   PERFORM pactwoven.custody_assert_spec(c,s);
   SELECT generation INTO spec_generation FROM pactwoven.custody_setup_specification_controls WHERE specification_id=s->>'id' ORDER BY generation DESC LIMIT 1;
  END IF;
  SELECT * INTO locked_control FROM pactwoven.custody_setup_controls WHERE setup_id=sid ORDER BY generation DESC LIMIT 1 FOR UPDATE;
  IF locked_control IS DISTINCT FROM control THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Setup control changed while resolving scope';END IF;
  control:=locked_control;
  -- Cancellation takes this compatible subsequence without requiring qualification.
  IF kind<>'cancel' THEN
   IF control.state<>'pending' OR spec_generation IS DISTINCT FROM(d->>'specificationControlGeneration')::int THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Setup control changed';END IF;
   IF(d->>'expiresAt')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='CS003',MESSAGE='Setup draft expired';END IF;
  END IF;
  generation:=control.generation;
  recordkind:=CASE kind WHEN 'challenge' THEN 'wallet_challenge' WHEN 'confirmation' THEN 'confirmation' WHEN 'confirm' THEN 'owner_binding' ELSE 'cancellation' END;
 END IF;
 at_time:=clock_timestamp();expires:=least((s->>'expiresAt')::timestamptz,(c#>>'{identity,expiresAt}')::timestamptz,at_time+interval '5 minutes');
 common:=jsonb_build_object('schemaVersion',1,'id',recordid,'setupId',sid,'version',version,'environment','development','organizationId',c->>'organizationId','responsibilityId',v->>'responsibilityId','actorId',c->>'actorId','issuedAt',pactwoven.mandate_instant(at_time),'expiresAt',pactwoven.mandate_instant(expires),'kind',recordkind);
 IF kind='prepare' THEN
  SELECT generation INTO spec_generation FROM pactwoven.custody_setup_specification_controls WHERE specification_id=s->>'id' ORDER BY generation DESC LIMIT 1;
  body:=common||jsonb_build_object('specification',pactwoven.custody_ref(s,pactwoven.custody_hash('specification',s)),'specificationControlGeneration',spec_generation,'predecessor',v->'previousDraft','prepareOperationId',opid);
 ELSIF kind='challenge' THEN
  IF EXISTS(SELECT 1 FROM pactwoven.custody_setup_records WHERE kind='wallet_challenge' AND body#>>'{draft,id}'=d->>'id') THEN RAISE EXCEPTION USING ERRCODE='CS005',MESSAGE='Recover the original wallet challenge';END IF;
  body:=common||jsonb_build_object('specification',d->'specification','draft',pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d)),'owner',s->'owner','wallet',s->'ownerWalletPublicKey',
   'organizationRegistrationUuid',s#>'{organization,registrationUuid}','responsibilityRegistrationUuid',s#>'{responsibility,registrationUuid}','setupOperationKey',s->'setupOperationKey','nonce',pactwoven.custody_nonce());
 ELSIF kind='confirmation' THEN
  SELECT body INTO ch FROM pactwoven.custody_setup_records WHERE id=(v->>'challengeId')::uuid AND kind='wallet_challenge';
  SELECT body INTO w FROM pactwoven.custody_setup_evidence WHERE id=(v->>'walletEvidenceId')::uuid AND kind='wallet';
  IF NOT pactwoven.custody_evidence_current((v->>'walletEvidenceId')::uuid,c->>'organizationId') THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Wallet verifier binding changed';END IF;
  IF ch IS NULL OR ch->>'setupId'<>sid::text OR ch->'draft' IS DISTINCT FROM pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d)) OR pactwoven.custody_hash('wallet_challenge',ch) IS DISTINCT FROM v->>'challengeHash'
   OR w IS NULL OR w->'challenge' IS DISTINCT FROM pactwoven.custody_ref(ch,pactwoven.custody_hash('wallet_challenge',ch)) OR w->'owner' IS DISTINCT FROM s->'owner' OR w->>'organizationId'<>c->>'organizationId' THEN RAISE EXCEPTION USING ERRCODE='CS004',MESSAGE='Exact wallet proof required';END IF;
  expires:=least(expires,(ch->>'expiresAt')::timestamptz,(w->>'expiresAt')::timestamptz);
  IF expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='CS003',MESSAGE='Wallet challenge expired';END IF;
  IF EXISTS(SELECT 1 FROM pactwoven.custody_setup_records WHERE kind='confirmation' AND body#>>'{intent,challenge,id}'=ch->>'id') THEN RAISE EXCEPTION USING ERRCODE='CS005',MESSAGE='Recover original confirmation';END IF;
  intent:=jsonb_build_object('schemaVersion',1,'purpose','custody_setup_owner_binding','environment','development','organizationId',c->>'organizationId','responsibilityId',v->>'responsibilityId','setupId',sid,'specification',d->'specification','challenge',w->'challenge','signatureHash',w->'signatureHash','owner',s->'owner','key',v->'confirmationKey','nonce',pactwoven.custody_nonce());
  body:=common||jsonb_build_object('expiresAt',pactwoven.mandate_instant(expires),'draft',pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d)),'walletEvidence',jsonb_build_object('id',w->'id','version',1,'recordHash',pactwoven.custody_hash('evidence',w)),
   'intent',intent,'intentHash',pactwoven.finance_hash(intent),'requestHash',pactwoven.finance_hash(jsonb_build_object('schemaVersion',1,'purpose','custody_setup_owner_binding','request',jsonb_build_object('nonce',intent->'nonce','key',intent->'key','intent',intent))));
 ELSIF kind='confirm' THEN
  SELECT body INTO cf FROM pactwoven.custody_setup_records WHERE id=(v->>'confirmationId')::uuid AND kind='confirmation';
  SELECT body INTO mf FROM pactwoven.custody_setup_evidence WHERE id=(v->>'mfaEvidenceId')::uuid AND kind='mfa';
  SELECT body INTO w FROM pactwoven.custody_setup_evidence WHERE id=(cf#>>'{walletEvidence,id}')::uuid AND kind='wallet';
  IF NOT pactwoven.custody_evidence_current((v->>'mfaEvidenceId')::uuid,c->>'organizationId') OR NOT pactwoven.custody_evidence_current((cf#>>'{walletEvidence,id}')::uuid,c->>'organizationId') THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Setup proof verifier binding changed';END IF;
  IF cf IS NULL OR cf->>'setupId'<>sid::text OR cf->'draft' IS DISTINCT FROM pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d))
   OR cf#>'{intent,owner}' IS DISTINCT FROM s->'owner' OR cf#>>'{intent,key}' IS DISTINCT FROM v->>'key' OR cf#>>'{intent,nonce}' IS DISTINCT FROM v->>'confirmationNonce'
   OR mf IS NULL OR mf->>'confirmationId' IS DISTINCT FROM cf->>'id' OR mf->'owner' IS DISTINCT FROM s->'owner' OR mf->>'organizationId'<>c->>'organizationId'
   OR mf->>'intentHash' IS DISTINCT FROM cf->>'intentHash' OR mf->>'requestHash' IS DISTINCT FROM cf->>'requestHash' OR w IS NULL THEN RAISE EXCEPTION USING ERRCODE='CS004',MESSAGE='Exact MFA and wallet attestations required';END IF;
  expires:=least(expires,(cf->>'expiresAt')::timestamptz,(mf->>'expiresAt')::timestamptz,(w->>'expiresAt')::timestamptz);
  IF expires<=clock_timestamp() OR(mf->>'observedAt')::timestamptz<clock_timestamp()-interval '20 seconds' THEN RAISE EXCEPTION USING ERRCODE='CS003',MESSAGE='Owner setup proof expired';END IF;
  IF EXISTS(SELECT 1 FROM pactwoven.custody_setup_evidence_uses WHERE evidence_id IN((mf->>'id')::uuid,(w->>'id')::uuid)) THEN RAISE EXCEPTION USING ERRCODE='CS005',MESSAGE='Setup proof already consumed';END IF;
  SELECT result INTO prep FROM pactwoven.custody_setup_operations WHERE id=(d->>'prepareOperationId')::uuid;
  generation:=pactwoven.financial_next_generation(control.generation);
  body:=common||jsonb_build_object('expiresAt',pactwoven.mandate_instant(expires),'purpose','INITIALIZE_EMPTY_CUSTODY','specification',s,'specificationRef',d->'specification',
   'specificationControlGeneration',d->'specificationControlGeneration','draft',pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d)),'challenge',cf#>'{intent,challenge}',
   'confirmation',pactwoven.custody_ref(cf,pactwoven.custody_hash('confirmation',cf)),'identityEvidence',jsonb_build_object('id',eid,'version',1,'recordHash',pactwoven.custody_hash('evidence',c->'identity')),
   'walletEvidence',cf->'walletEvidence','mfaEvidence',jsonb_build_object('id',mf->'id','version',1,'recordHash',pactwoven.custody_hash('evidence',mf)),'signatureHash',w->'signatureHash',
   'prepareOperation',jsonb_build_object('id',prep->'id','key',prep->'key','commandHash',prep->'commandHash'),'confirmOperation',jsonb_build_object('id',opid,'key',v->'key','commandHash',hash),'controlGeneration',generation);
 ELSE
  IF control.state='cancelled' OR control.generation IS DISTINCT FROM(v->>'expectedSetupControlGeneration')::int THEN RAISE EXCEPTION USING ERRCODE='CS002',MESSAGE='Setup control changed';END IF;
  generation:=pactwoven.financial_next_generation(control.generation);
  body:=common||jsonb_build_object('draft',pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d)),'previousControlGeneration',control.generation,'controlGeneration',generation);
 END IF;
 -- Last clock checks happen after all potentially blocking scope and evidence work.
 IF(c#>>'{identity,observedAt}')::timestamptz<clock_timestamp()-interval '20 seconds' OR(c#>>'{identity,expiresAt}')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Owner observation expired at effect';END IF;
 PERFORM pactwoven.custody_principal(c->>'organizationId','writer');
 IF NOT pactwoven.custody_evidence_current(eid,c->>'organizationId') THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Identity verifier expired at effect';END IF;
 IF EXISTS(SELECT 1 FROM pactwoven.memberships WHERE environment='development' AND organization_id=c->>'organizationId' AND actor_id=c->>'actorId' AND expires_at<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Owner expired at effect';END IF;
 IF kind<>'cancel' AND expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='CS003',MESSAGE='Setup expired at effect';END IF;
 PERFORM pactwoven.custody_require('record',body);target:=pactwoven.custody_ref(body,pactwoven.custody_hash(recordkind,body));
 result:=jsonb_build_object('schemaVersion',1,'id',opid,'organizationId',c->>'organizationId','actorId',c->>'actorId','responsibilityId',v->>'responsibilityId','kind',kind,'key',v->'key','commandHash',hash,'setupId',sid,'target',target,'body',body,'financialState',NULL);
 INSERT INTO pactwoven.custody_setup_operations VALUES(opid,c->>'organizationId',c->>'actorId',v->>'responsibilityId',kind,v->>'key',hash,v,result);
 INSERT INTO pactwoven.custody_setup_records(id,setup_id,kind,version,body,operation_id) VALUES(recordid,sid,recordkind,version,body,opid);
 IF kind IN('prepare','confirm','cancel') THEN INSERT INTO pactwoven.custody_setup_controls VALUES(sid,generation,CASE WHEN kind='prepare' THEN recordid ELSE control.draft_id END,CASE kind WHEN 'confirm' THEN 'confirmed' WHEN 'cancel' THEN 'cancelled' ELSE 'pending' END,opid);END IF;
 INSERT INTO pactwoven.custody_setup_audit VALUES(opid,result-'body');INSERT INTO pactwoven.custody_setup_outbox VALUES(opid,result-'body');
 IF kind='confirm' THEN INSERT INTO pactwoven.custody_setup_evidence_uses VALUES((w->>'id')::uuid,opid),((mf->>'id')::uuid,opid);END IF;
 RETURN result;
END $$;
CREATE FUNCTION pactwoven.custody_setup_recover(eid uuid,v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb;r jsonb;BEGIN PERFORM pactwoven.custody_require('lookup',v);c:=pactwoven.custody_context(eid,v->>'responsibilityId','writer');
 SELECT result INTO r FROM pactwoven.custody_setup_operations WHERE organization_id=c->>'organizationId' AND actor_id=c->>'actorId' AND responsibility_id=v->>'responsibilityId' AND kind=v->>'kind' AND key=v->>'key';
 IF r IS NOT NULL AND r->>'commandHash'<>v->>'commandHash' THEN RAISE EXCEPTION USING ERRCODE='CS005',MESSAGE='Original setup request differs';END IF;RETURN r;
END $$;
CREATE FUNCTION pactwoven.custody_setup_read(eid uuid,rid text,sid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c jsonb;d jsonb;b jsonb;control record;BEGIN c:=pactwoven.custody_context(eid,rid,'writer');
 IF NOT EXISTS(SELECT 1 FROM pactwoven.custody_setup_anchors WHERE id=sid AND organization_id=c->>'organizationId' AND responsibility_id=rid) THEN RETURN NULL;END IF;
 SELECT * INTO control FROM pactwoven.custody_setup_controls WHERE setup_id=sid ORDER BY generation DESC LIMIT 1;
 SELECT body INTO d FROM pactwoven.custody_setup_records WHERE id=control.draft_id;
 IF d->>'actorId' IS DISTINCT FROM c->>'actorId' THEN RAISE EXCEPTION USING ERRCODE='CS001',MESSAGE='Original owner setup required';END IF;
 SELECT body INTO b FROM pactwoven.custody_setup_records WHERE setup_id=sid AND kind='owner_binding';
 RETURN jsonb_build_object('schemaVersion',1,'setupId',sid,'draft',d,'draftHash',pactwoven.custody_hash('draft',d),'controlGeneration',control.generation,
  'state',CASE WHEN control.state='cancelled' THEN 'cancelled' WHEN (d->>'expiresAt')::timestamptz<=clock_timestamp() OR(b IS NOT NULL AND(b->>'expiresAt')::timestamptz<=clock_timestamp()) THEN 'expired' ELSE control.state END,'binding',b);
END $$;
CREATE FUNCTION pactwoven.custody_append_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE prior jsonb;expected int;BEGIN
 IF TG_TABLE_NAME='custody_setup_principals' THEN
  PERFORM id FROM pactwoven.organizations WHERE environment=NEW.environment AND id=NEW.organization_id FOR UPDATE;
  SELECT to_jsonb(p) INTO prior FROM pactwoven.custody_setup_principals p WHERE principal_oid=NEW.principal_oid AND organization_id=NEW.organization_id ORDER BY version DESC LIMIT 1;
  IF NEW.version<>coalesce((prior->>'version')::int,0)+1 OR(prior IS NOT NULL AND(to_jsonb(NEW)-ARRAY['version','active','expires_at']) IS DISTINCT FROM(prior-ARRAY['version','active','expires_at']))
   OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE oid=NEW.principal_oid AND rolname=NEW.principal_name AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
  THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Immutable contiguous principal binding required';END IF;
 ELSIF TG_TABLE_NAME='custody_setup_specifications' THEN
  PERFORM id FROM pactwoven.organizations WHERE environment='development' AND id=NEW.body#>>'{organization,id}' FOR UPDATE;
  SELECT body INTO prior FROM pactwoven.custody_setup_specifications WHERE id=NEW.id ORDER BY version DESC LIMIT 1;
  IF NEW.version<>coalesce((prior->>'version')::int,0)+1 OR(prior IS NOT NULL AND NEW.body->'predecessor' IS DISTINCT FROM pactwoven.custody_ref(prior,pactwoven.custody_hash('specification',prior)))
   OR(prior IS NOT NULL AND(NEW.body#>'{organization,id}' IS DISTINCT FROM prior#>'{organization,id}' OR NEW.body#>'{responsibility,id}' IS DISTINCT FROM prior#>'{responsibility,id}' OR NEW.body->'setupOperationKey' IS DISTINCT FROM prior->'setupOperationKey'))
  THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Immutable contiguous specification required';END IF;
 ELSIF TG_TABLE_NAME='custody_setup_specification_controls' THEN
  PERFORM o.id FROM pactwoven.organizations o JOIN pactwoven.custody_setup_specifications s ON o.id=s.body#>>'{organization,id}' AND o.environment='development' WHERE s.id=NEW.specification_id AND s.version=NEW.version FOR UPDATE OF o;
  SELECT to_jsonb(p) INTO prior FROM pactwoven.custody_setup_specification_controls p WHERE specification_id=NEW.specification_id ORDER BY generation DESC LIMIT 1;
  IF NEW.generation<>coalesce((prior->>'generation')::int,-1)+1 OR NEW.version<coalesce((prior->>'version')::int,1) THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Contiguous specification control required';END IF;
 END IF;RETURN NEW;
END $$;
CREATE FUNCTION pactwoven.custody_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE opid uuid;op pactwoven.custody_setup_operations%ROWTYPE;r pactwoven.custody_setup_records%ROWTYPE;ctrl pactwoven.custody_setup_controls%ROWTYPE;prev pactwoven.custody_setup_controls%ROWTYPE;anchor pactwoven.custody_setup_anchors%ROWTYPE;d jsonb;expected_kind text;item record;BEGIN
 IF TG_TABLE_NAME='custody_setup_anchors' THEN
  IF NOT EXISTS(SELECT 1 FROM pactwoven.custody_setup_controls WHERE setup_id=NEW.id AND generation=0) THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Setup anchor has no initial operation';END IF;RETURN NULL;
 END IF;
 opid:=CASE WHEN TG_TABLE_NAME='custody_setup_operations' THEN(to_jsonb(NEW)->>'id')::uuid ELSE(to_jsonb(NEW)->>'operation_id')::uuid END;
 SELECT * INTO op FROM pactwoven.custody_setup_operations WHERE id=opid;
 SELECT * INTO r FROM pactwoven.custody_setup_records WHERE operation_id=opid;
 SELECT * INTO anchor FROM pactwoven.custody_setup_anchors WHERE id=r.setup_id;
 expected_kind:=CASE op.kind WHEN 'prepare' THEN 'draft' WHEN 'challenge' THEN 'wallet_challenge' WHEN 'confirmation' THEN 'confirmation' WHEN 'confirm' THEN 'owner_binding' WHEN 'cancel' THEN 'cancellation' END;
 IF op.id IS NULL OR r.id IS NULL OR expected_kind IS NULL OR r.kind<>expected_kind OR anchor.organization_id<>op.organization_id OR anchor.responsibility_id<>op.responsibility_id
 OR r.body->>'organizationId'<>op.organization_id OR r.body->>'responsibilityId'<>op.responsibility_id OR r.body->>'actorId'<>op.actor_id
 OR op.command_hash IS DISTINCT FROM pactwoven.custody_command_hash(op.organization_id,op.actor_id,op.command)
 OR op.command->>'key' IS DISTINCT FROM op.key OR op.command->>'kind' IS DISTINCT FROM op.kind
 OR op.result IS DISTINCT FROM jsonb_build_object('schemaVersion',1,'id',op.id,'organizationId',op.organization_id,'actorId',op.actor_id,'responsibilityId',op.responsibility_id,
  'kind',op.kind,'key',op.key,'commandHash',op.command_hash,'setupId',r.setup_id,'target',pactwoven.custody_ref(r.body,r.hash),'body',r.body,'financialState',NULL)
 OR NOT EXISTS(SELECT 1 FROM pactwoven.custody_setup_audit WHERE operation_id=opid AND body=op.result-'body')
 OR NOT EXISTS(SELECT 1 FROM pactwoven.custody_setup_outbox WHERE operation_id=opid AND body=op.result-'body') THEN
 RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Exact reciprocal setup record operation audit and outbox required';END IF;
 PERFORM pactwoven.custody_require('command',op.command);
 SELECT * INTO ctrl FROM pactwoven.custody_setup_controls WHERE operation_id=opid;
 IF op.kind IN('prepare','confirm','cancel') THEN
  SELECT * INTO prev FROM pactwoven.custody_setup_controls WHERE setup_id=r.setup_id AND generation=ctrl.generation-1;
  IF ctrl.operation_id IS NULL OR ctrl.setup_id<>r.setup_id OR(ctrl.generation=0 AND(op.kind<>'prepare' OR r.version<>1))
   OR(ctrl.generation>0 AND prev.operation_id IS NULL) OR ctrl.state<>(CASE op.kind WHEN 'prepare' THEN 'pending' WHEN 'confirm' THEN 'confirmed' ELSE 'cancelled' END) THEN
   RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Contiguous exact setup control required';END IF;
  IF op.kind='prepare' THEN
   SELECT body INTO d FROM pactwoven.custody_setup_records WHERE id=prev.draft_id;
   IF ctrl.draft_id<>r.id OR r.body->>'prepareOperationId'<>opid::text OR r.body->'predecessor' IS DISTINCT FROM op.command->'previousDraft'
    OR(ctrl.generation=0 AND r.body->'predecessor'<>'null'::jsonb)
    OR(ctrl.generation>0 AND(r.body->'predecessor' IS DISTINCT FROM pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d)) OR r.version<>(d->>'version')::int+1)) THEN
    RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Exact draft predecessor operation required';END IF;
  ELSE
   SELECT body INTO d FROM pactwoven.custody_setup_records WHERE id=ctrl.draft_id;
   IF ctrl.draft_id<>prev.draft_id OR r.body->'draft' IS DISTINCT FROM pactwoven.custody_ref(d,pactwoven.custody_hash('draft',d))
     OR(r.body->>'controlGeneration')::int<>ctrl.generation OR(op.kind='confirm' AND prev.state<>'pending') THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Exact controlled draft required';END IF;
  END IF;
 ELSIF ctrl.operation_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Proof preparation cannot change setup control';END IF;
 IF op.kind='confirm' THEN
  IF (SELECT count(*) FROM pactwoven.custody_setup_evidence_uses WHERE operation_id=opid)<>2 THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Both proof consumptions required';END IF;
  FOR item IN SELECT e.id,e.kind,e.body,e.hash FROM pactwoven.custody_setup_evidence e JOIN pactwoven.custody_setup_evidence_uses u ON u.evidence_id=e.id WHERE u.operation_id=opid LOOP
   IF item.kind NOT IN('wallet','mfa') OR r.body->(CASE item.kind WHEN 'wallet' THEN 'walletEvidence' ELSE 'mfaEvidence' END) IS DISTINCT FROM jsonb_build_object('id',item.id,'version',1,'recordHash',item.hash) THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Exact one-use proof consumption required';END IF;
  END LOOP;
 ELSE IF EXISTS(SELECT 1 FROM pactwoven.custody_setup_evidence_uses WHERE operation_id=opid) THEN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Only owner confirmation consumes proofs';END IF;END IF;
 RETURN NULL;
END $$;
CREATE FUNCTION pactwoven.custody_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION USING ERRCODE='CS007',MESSAGE='Custody setup records and history are immutable';END $$;
DO $$ DECLARE item text;routine regprocedure;BEGIN
 FOREACH item IN ARRAY ARRAY['custody_setup_principals','custody_setup_organization_ids','custody_setup_responsibility_ids','custody_setup_specifications','custody_setup_specification_controls',
 'custody_setup_evidence','custody_setup_anchors','custody_setup_records','custody_setup_controls','custody_setup_operations','custody_setup_audit','custody_setup_outbox','custody_setup_evidence_uses'] LOOP
  EXECUTE format('ALTER TABLE pactwoven.%I ENABLE ROW LEVEL SECURITY',item);
  EXECUTE format('REVOKE ALL ON pactwoven.%I FROM PUBLIC,pactwoven_runtime,pactwoven_provisioner,pactwoven_access_provisioner,pactwoven_mandate_writer,pactwoven_finance_observer,pactwoven_custody_setup_verifier,pactwoven_custody_setup_writer',item);
  EXECUTE format('CREATE TRIGGER custody_no_mutation BEFORE UPDATE OR DELETE ON pactwoven.%I FOR EACH ROW EXECUTE FUNCTION pactwoven.custody_immutable()',item);
  EXECUTE format('CREATE TRIGGER custody_no_truncate BEFORE TRUNCATE ON pactwoven.%I FOR EACH STATEMENT EXECUTE FUNCTION pactwoven.custody_immutable()',item);
  IF item IN('custody_setup_principals','custody_setup_specifications','custody_setup_specification_controls') THEN EXECUTE format('CREATE TRIGGER custody_append_guard BEFORE INSERT ON pactwoven.%I FOR EACH ROW EXECUTE FUNCTION pactwoven.custody_append_guard()',item);END IF;
  IF item IN('custody_setup_anchors','custody_setup_records','custody_setup_controls','custody_setup_operations','custody_setup_audit','custody_setup_outbox','custody_setup_evidence_uses') THEN
   EXECUTE format('CREATE CONSTRAINT TRIGGER custody_complete AFTER INSERT ON pactwoven.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pactwoven.custody_complete()',item);END IF;
 END LOOP;
 FOR routine IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='pactwoven' AND p.proname LIKE 'custody_%' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,pactwoven_runtime,pactwoven_provisioner,pactwoven_access_provisioner,pactwoven_mandate_writer,pactwoven_finance_observer,pactwoven_custody_setup_verifier,pactwoven_custody_setup_writer',routine);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION pactwoven.custody_setup_attest(jsonb) TO pactwoven_custody_setup_verifier;
GRANT EXECUTE ON FUNCTION pactwoven.custody_setup_command(uuid,jsonb),pactwoven.custody_setup_read(uuid,text,uuid),pactwoven.custody_setup_recover(uuid,jsonb) TO pactwoven_custody_setup_writer;
COMMIT;
